 $('navigationToggle').setAttribute('aria-pressed',String(navigationMode));$('navigationToggle').textContent=navigationMode?'🧭 Navigazione attiva':'🧭 Navigazione';$('navBack').disabled=!navigationHistory.length;$('setRoot').classList.toggle('hidden',selection.type!=='person'||selection.id===state.rootId);$('refReset').textContent='⌂ '+name(state.rootId);$('refReset').title='Torna al riferimento base: '+name(state.rootId);$('home').title='Vai a '+name(focusId);$('home').setAttribute('aria-label',$('home').title);$('moveBefore').classList.toggle('hidden',!arrangeMode||selection.type!=='person');$('moveAfter').classList.toggle('hidden',!arrangeMode||selection.type!=='person');
