 if(act.startsWith('newunionparent:')){const role=act.slice('newunionparent:'.length),u=union(current.id);const run=()=>{const p=addPerson({gender:role==='fatherId'?'m':'f'});u[role]=p.id;save();select('person',p.id,{open:true,focus:true});toast('Nuovo genitore: completa la scheda');};if(u[role])confirmModal('Sostituire il genitore?',`Il nuovo genitore sostituirà ${name(u[role])} nell’unione e per tutti i ${u.children.length} figli.`,run,'Sostituisci');else run();return;}
 if(act==='newsibling'){const ref=person(current.id);createAndOpen({gender:'u'},{type:'sibling',referenceId:ref.id});return;}
