function itemFromKey(key){const split=key.indexOf(':');return {kind:key.slice(0,split),id:key.slice(split+1)};}
function pointFor(key){const {kind,id}=itemFromKey(key);return (kind==='union'?unionLayout:layout)[id];}
function rememberUndo(){undoPositions.push({key:manualKey(),snapshot:copy(freezePositions()),order:copy(state.layoutOrder?.[focusId]||[])});if(undoPositions.length>30)undoPositions.shift();}
function undoMove(){const index=undoPositions.findLastIndex(entry=>entry.key===manualKey());if(index<0)return;const entry=undoPositions.splice(index,1)[0];state.manualLayouts[manualKey()]=entry.snapshot;state.layoutOrder[focusId]=entry.order;save();render();toast('Disposizione precedente ripristinata');}
function upstreamItems(unionId){const result=new Set(),todo=[{kind:'union',id:unionId}];while(todo.length){const item=todo.pop(),key=itemKey(item.kind,item.id);if(result.has(key))continue;result.add(key);if(item.kind==='union'){const u=union(item.id);if(u)for(const id of [u.fatherId,u.motherId])if(id)todo.push({kind:'person',id});}else{const u=person(item.id)?.birthUnionId;if(u)todo.push({kind:'union',id:u});}}return new Set([...result].filter(key=>pointFor(key)));}
