function renderAppearancePanel(){const styles=styleSettings(),labels={acquired:'Acquisiti',collateral:'Zii, cugini, prozii e altri parenti',half:'Fratellastri dei parenti diretti e loro discendenti'};$('appearanceBody').innerHTML=`<fieldset><legend>Distanza di sangue · prova</legend><label class="appearance-check"><input type="checkbox" data-style-class="kinship" data-style-field="enabled" ${styles.kinship.enabled?'checked':''}> Sfumatura progressiva dei parenti distanti</label><p class="muted">Con navigazione attiva le distanze seguono la persona esplorata; altrimenti seguono il riferimento base. I discendenti dei rami lontani diventano più discreti. È una distanza genealogica, non una stima del DNA.</p><label class="appearance-check"><input type="checkbox" data-style-class="kinship" data-style-field="keepDirect" ${styles.kinship.keepDirect?'checked':''}> Mantieni in evidenza antenati e discendenti diretti</label><label class="appearance-check"><input type="checkbox" data-style-class="kinship" data-style-field="shrink" ${styles.kinship.shrink?'checked':''}> Riduci anche le dimensioni delle card lontane</label><label class="appearance-check"><input type="checkbox" data-style-class="kinship" data-style-field="keepCousins" ${styles.kinship.keepCousins?'checked':''}> Mantieni in evidenza cugini di primo grado, discendenti e partner</label><p class="muted">Gli acquisiti seguono la distanza del partner, mantenendo le preferenze dedicate agli acquisiti.</p><label>Intensità<input aria-label="Intensità distanza di sangue" type="range" min="10" max="100" value="${Math.round(styles.kinship.strength*100)}" data-style-class="kinship" data-style-field="strength"></label></fieldset>`+Object.entries(labels).map(([key,label])=>{const value=styles[key];return `<fieldset><legend>${label}</legend><label class="appearance-check"><input type="checkbox" data-style-class="${key}" data-style-field="visible" ${value.visible?'checked':''}> Mostra queste persone</label><label>Dimensione<select data-style-class="${key}" data-style-field="size"><option value="small" ${value.size==='small'?'selected':''}>Piccola</option><option value="normal" ${value.size==='normal'?'selected':''}>Normale</option></select></label><label>Opacità <output id="opacity-${key}">${Math.round(value.opacity*100)}%</output><input aria-label="Opacità ${label}" type="range" min="5" max="100" value="${Math.round(value.opacity*100)}" data-style-class="${key}" data-style-field="opacity"></label>${key==='acquired'?`<label class="appearance-check"><input id="showAcquiredParents" type="checkbox" data-style-class="acquired" data-style-field="parentsVisible" ${value.parentsVisible?'checked':''}> Mostra anche padre e madre degli acquisiti</label><label>Opacità dei loro genitori <output id="opacity-parents">${Math.round(value.parentOpacity*100)}%</output><input aria-label="Opacità genitori degli acquisiti" type="range" min="5" max="100" value="${Math.round(value.parentOpacity*100)}" data-style-class="acquired" data-style-field="parentOpacity"></label><small>Soltanto i genitori; gli altri rami si aprono scegliendo un nuovo riferimento.</small>`:''}</fieldset>`;}).join('');}
